def variants(key, title, comps):
    VAR[key] = {}; out = []
    for c, (lim, txt) in comps.items():
        VAR[key][c] = f'Vlad the Impaler: {title}' if len(comps) == 1 else f'Vlad the Impaler: {title} - {c}'
        out.append((VAR[key][c], lim, txt))
    return out
def L(**kw):
    out = {}
    for k, v in kw.items():
        cat = k.replace('_', ' ')
        if isinstance(v, tuple):
            lo, hi = v; d = {}
            if lo: d['min'] = lo
            if hi and hi < 100: d['max'] = hi
            out[cat] = d
        else: out[cat] = {'max': v}
    return out
def lord_opts(mounted_plate=(0, 0), dis_plate=(4, 6), horse=True, warhorse=4, lance=4, cloth=4, plate_b=6, polearm=4, bow=None, heavy=None):
    """Hungarian-style plate/barding option set. mounted_plate: costs for partial/full plate when mounted; dis_plate when dismounted."""
    o = []
    if heavy is not None: o.append(('Heavy armour (replaces light armour)', heavy[0]) if heavy[0] is not None else None)
    o += [('Partial plate armour, if mounted (replaces heavy armour)', mounted_plate[0]), ('Partial plate armour, if dismounted (replaces heavy armour)', dis_plate[0]),
          ('Full plate armour, if mounted (replaces heavy armour)', mounted_plate[1]), ('Full plate armour, if dismounted (replaces heavy armour)', dis_plate[1]),
          ('Lance', lance), ('Ride a horse', 0), ('Ride a warhorse', warhorse), ('Cloth barding', cloth), ('Plate barding', plate_b), ('Halberd', polearm), ('Double-handed weapon', polearm)]
    return [x for x in o if x]
