# ====================================================================== OTTOMANS (book pp.36-43)
SPC, VAS = 'Kapikulu & Special Troops', 'Vassals'
OT = []
def ot_gen(name, mname, stats, pts, rules, extra, bow=True, horse_cost=0, wh_cost=None, sp=None):
    base = ['Hand Weapon', 'Light Armour', 'Shield'] + (['Bow'] if bow else [])
    opts = [('Thrusting spear', 4), ('Ride a horse', 0), ('Cloth barding', 4), ('Plate barding', 6), ('Halberd, if dismounted', 4), ('Heavy armour (replaces light armour)', 2),
            ('Partial plate armour, if mounted (replaces light armour)', 2), ('Partial plate armour, if dismounted (replaces light armour)', 4)]
    return U(CH, name, [M(mname, stats, pts, weapons=base, rules=rules, options=opts)], extra, mx=1, page='38')
OTE = 'Hand weapon, light armour, shield, and bow. May have a thrusting spear (+4 pts) and must have a horse (free) if mounted. May have cloth (+4 pts) or plate barding (+6 pts). May have halberd (+4 pts) if dismounted. May take heavy (+2 pts) or partial plate armour (+2 if mounted, +4 pts if dismounted). '
