    o += [('Partial plate armour, if mounted (replaces heavy armour)', 0), ('Partial plate armour, if dismounted (replaces heavy armour)', 4), ('Full plate armour, if mounted (replaces heavy armour)', 0), ('Full plate armour, if dismounted (replaces heavy armour)', 6)]
    return o
